  "title": "Binary tree diameter",
  "company": "Amazon",
  "prompt": "tree_diameter(root): longest path length in edges between any two nodes.\nInput: level-order (#=null). Output: integer.",
  "hint": "DFS heights; diameter through node = left_height + right_height.",
  "starter": "def tree_diameter(root):\n    return 0\n",
  "solution": "def tree_diameter(root):\n    best = 0\n    def depth(node):\n        nonlocal best\n        if node is None:\n            return 0\n        L, R = depth(node.left), depth(node.right)\n        best = max(best, L + R)\n        return 1 + max(L, R)\n    depth(root)\n    return best",
  "wrapSuffix": "\nfrom collections import deque\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(tokens):\n    if not tokens or tokens[0] == '#':\n        return None\n    root = TreeNode(int(tokens[0]))\n    q = deque([root])\n    i = 1\n    while q and i < len(tokens):\n        node = q.popleft()\n        if i < len(tokens) and tokens[i] != '#':\n            node.left = TreeNode(int(tokens[i]))\n            q.append(node.left)\n        i += 1\n        if i < len(tokens) and tokens[i] != '#':\n            node.right = TreeNode(int(tokens[i]))\n            q.append(node.right)\n        i += 1\n    return root\n\nimport sys\ntokens = sys.stdin.read().split()\nprint(tree_diameter(build_tree(tokens)))\n",
