  "company": "Citadel",
  "prompt": "class MedianFinder: add_num(num), find_median().\nInput: q then lines ADD x | MED. Output: one median per MED.",
  "hint": "Two heaps: max-heap lower half, min-heap upper half.",
  "starter": "class MedianFinder:\n    def __init__(self):\n        self.a = []\n    def add_num(self, num):\n        self.a.append(num)\n    def find_median(self):\n        return 0\n",
  "solution": "import heapq\nclass MedianFinder:\n    def __init__(self):\n        self.lo = []  # max-heap via negatives\n        self.hi = []  # min-heap\n    def add_num(self, num):\n        heapq.heappush(self.lo, -num)\n        heapq.heappush(self.hi, -heapq.heappop(self.lo))\n        if len(self.hi) > len(self.lo):\n            heapq.heappush(self.lo, -heapq.heappop(self.hi))\n    def find_median(self):\n        if len(self.lo) > len(self.hi):\n            return float(-self.lo[0])\n        return (-self.lo[0] + self.hi[0]) / 2.0",
  "wrapSuffix": "\nimport sys\nlines = sys.stdin.read().strip().splitlines()\nmf = MedianFinder()\nout = []\nfor line in lines[1:]:\n    parts = line.split()\n    if parts[0] == 'ADD':\n        mf.add_num(int(parts[1]))\n    else:\n        med = mf.find_median()\n        if float(med).is_integer():\n            out.append(str(int(med)))\n        else:\n            out.append(f\"{med:.1f}\")\nprint('\\n'.join(out))\n",
